import React, { useState } from 'react';

const TodoItem = ({ todo, toggleTodo, editTodo, deleteTodo }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [editText, setEditText] = useState(todo.text);

    const handleEdit = () => {
        if (isEditing && editText.trim()) {
            editTodo(todo.id, editText.trim());
        }
        setIsEditing(!isEditing);
    };

    const handleCancel = () => {
        setEditText(todo.text);
        setIsEditing(false);
    };

    return (
        <div className="card mb-2 border-start border-4 border-primary">
            <div className="card-body py-3">
                <div className="d-flex align-items-center gap-3">
                    <input 
                        type="checkbox" 
                        checked={todo.completed} 
                        onChange={() => toggleTodo(todo.id)}
                        className="form-check-input m-0"
                        style={{width: '1.5rem', height: '1.5rem', cursor: 'pointer'}}
                    />

                    {isEditing ? (
                        <input
                            type="text"
                            value={editText}
                            onChange={(e) => setEditText(e.target.value)}
                            className="form-control"
                            autoFocus
                        />
                    ) : (
                        <span className={`flex-grow-1 ${todo.completed ? 'text-decoration-line-through text-muted' : ''}`} style={{fontSize: '1.1rem'}}>
                            {todo.text}
                        </span>
                    )}

                    <div className="btn-group" role="group">
                        {isEditing ? (
                            <>
                                <button onClick={handleEdit} className="btn btn-success btn-sm">
                                    <i className="bi bi-check-lg"></i>
                                </button>
                                <button onClick={handleCancel} className="btn btn-secondary btn-sm">
                                    <i className="bi bi-x-lg"></i>
                                </button>
                            </>
                        ) : (
                            <>
                                <button onClick={() => setIsEditing(true)} className="btn btn-warning btn-sm">
                                    <i className="bi bi-pencil"></i>
                                </button>
                                <button onClick={() => deleteTodo(todo.id)} className="btn btn-danger btn-sm">
                                    <i className="bi bi-trash"></i>
                                </button>
                            </>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default TodoItem;
